// components/Home.js
import React, { useEffect, useState, Suspense, lazy } from "react";
import bgVideo from "./Assets/blueblockoptician.mp4";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTimes } from "@fortawesome/free-solid-svg-icons";
const CategoryCarousel = lazy(() => import("./Categories"));
const Home = () => {
  // Kenya locations
  const [areas, setAreas] = useState({});
  const [counties, setCounties] = useState([]);
  const [constituencies, setConstituencies] = useState([]);
  const [wards, setWards] = useState([]);

  // Step 1 booking details
  const [selectedCounty, setSelectedCounty] = useState("");
  const [selectedConstituency, setSelectedConstituency] = useState("");
  const [selectedWard, setSelectedWard] = useState("");
  const [service, setService] = useState("");
  const [budget, setBudget] = useState("");
  const [appointmentDate, setAppointmentDate] = useState("");
  const [showBookingForm, setShowBookingForm] = useState(false);
  // Step control
  const [showConfirmation, setShowConfirmation] = useState(false);

  // Step 2 customer details
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [appointmentTime, setAppointmentTime] = useState("");

  // Today's date
  const today = new Date().toISOString().split("T")[0];

  // Maximum booking date (1 month ahead)
  const maxDate = new Date(
    new Date().setMonth(new Date().getMonth() + 1)
  )
    .toISOString()
    .split("T")[0];

const [showAppointmentPopup, setShowAppointmentPopup] = useState(false);
  // WhatsApp confirmation
  const handleWhatsAppBooking = () => {
    if (
      !fullName ||
      !phone ||
      !email ||
      !appointmentTime
    ) {
      alert("Please fill in all your personal details.");
      return;
    }

const message = `
BLUE BLOCK OPTICS APPOINTMENT REQUEST
* Name: ${fullName}
* Phone: ${phone}
* Email: ${email}
* Location
> County: ${selectedCounty}
> Constituency: ${selectedConstituency}
> Ward: ${selectedWard}
* Service: ${service}
* Appointment Date: ${appointmentDate}
* Appointment Time: ${appointmentTime}
* Budget: ${budget}
_ I would like to confirm my appointment. _
`;
    // WhatsApp number
    const whatsappNumber=process.env.REACT_APP_WHATSAPP_NUMBER;

    const url = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(
      message
    )}`;

    window.open(url, "_blank");
  };
  // Fetch counties
  useEffect(() => {
    fetch(
      "https://kenyaareadata.vercel.app/api/areas?apiKey=keyPub1569gsvndc123kg9sjhg"
    )
      .then((response) => response.json())
      .then((data) => {
        setAreas(data);
        setCounties(Object.keys(data));
      })
      .catch(() => {});
  }, []);


  // Update constituencies
  useEffect(() => {
    if (selectedCounty && areas[selectedCounty]) {
      setConstituencies(Object.keys(areas[selectedCounty]));
      setSelectedConstituency("");
      setSelectedWard("");
      setWards([]);
    }
  }, [selectedCounty, areas]);


  // Update wards
  useEffect(() => {
    if (
      selectedCounty &&
      selectedConstituency
    ) {
      setWards(
        areas[selectedCounty][selectedConstituency] || []
      );

      setSelectedWard("");
    }
  }, [
    selectedCounty,
    selectedConstituency,
    areas
  ]);
const handleAppointmentWhatsApp = () => {
  const message = `
Hello Blue Block Optics,
I would like to book an Eye Check Up appointment.
* Full Name: ${fullName}
* Phone Number: ${phone}
* Email Address: ${email}
* Preferred Time: ${appointmentTime}
Thank you.
`;

  const whatsappNumber=process.env.REACT_APP_WHATSAPP_NUMBER;
 
  const url = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;

  window.open(url, "_blank");
};

  return (
    <section className="relative min-h-screen w-full overflow-hidden">

      {/* Background Video */}
      <video
        className="absolute top-0 left-0 w-full h-full object-cover"
        src={bgVideo}
        autoPlay
        loop
        muted
        playsInline
      />

      {/* Dark Overlay */}
      <div className="absolute inset-0 bg-black/70"></div>


      <div className="relative z-10 container mx-auto px-4 md:px-8 py-12 md:py-20">

        <div className="flex flex-col lg:flex-row items-center gap-10 lg:gap-16">


          {/* Hero Left Side */}
          <div className="w-full lg:w-1/2 text-grey">


            <h1 className="text-white text-4xl md:text-4xl lg:text-5xl font-black leading-tight mb-4">
              See the World With Perfect
              <span className="text-sky-400">
                {" "}Clarity
              </span>
            </h1>
            <p className="text-lg text-gray-200 mb-6 max-w-xl">
              Blue Block Optics provides professional eye examinations,
              prescription lenses, stylish frames, reading glasses,
              and personalized vision care designed around your lifestyle.
            </p>
            <p className="text-lg text-gray-200 mb-6 max-w-xl">
              Our focus is on providing instant and same-day eyewear delivery, ensuring our customers receive the glasses they need quickly, affordably, and with the highest level of professionalism.
            </p>
            
          <button
          onClick={() => setShowAppointmentPopup(true)}
          className="bg-sky-400 hover:bg-sky-700 px-6 py-3 rounded-lg font-bold text-white transition"
          >
          Book Us Now →
          </button>
          </div>
          {/* right side hero */}
          <div className="w-full lg:w-1/2 relative overflow-visible"> 
          <div className="relative z-10">
  <Suspense
    fallback={
      <div className="flex items-center justify-center h-[450px]">
        <div className="w-10 h-10 border-4 border-sky-400 border-t-transparent rounded-full animate-spin" />
      </div>
    }
  >
    <CategoryCarousel />
  </Suspense>
</div>
          {/* appointment button */}
          {!showBookingForm && (
  <div className="flex justify-center mt-4">
  <button
    onClick={() => setShowBookingForm(true)}
    className="
      w-full
      max-w-md
      bg-sky-400
      hover:bg-red-700
      text-black
      py-4
      rounded-lg
      font-bold
      text-lg
      shadow-xl
      transition-all
    "
  >
    Appointment
  </button>
</div>
)}

        {/* overlay form */}
{showBookingForm && (
  <div
    className="
      absolute
  bottom-0
  left-0
  z-50
  w-full
  lg:max-w-md
  bg-white/95
  backdrop-blur-md
  p-6
  border
  border-sky-400
  rounded-2xl
  shadow-2xl
  max-h-[80vh] overflow-y-auto
  animate-slideUp
    "
  >
  <div className="flex items-center justify-between mb-5">
  <h2 className="text-xl font-semibold text-gray-800">
    {showConfirmation
      ? "Confirm Your Appointment"
      : "Book Your Appointment"}
  </h2>

  <button
    onClick={() => {
      setShowBookingForm(false);
      setShowConfirmation(false);
    }}
    className="
      flex
      items-center
      justify-center
      w-8
      h-8
      rounded-full
      bg-gray-100
      hover:bg-red-100
      text-gray-600
      hover:text-red-600
      transition
    "
  >
    <FontAwesomeIcon icon={faTimes} />
  </button>
</div>

   {!showConfirmation ? (
                <>
                  {/* Location Selection */}
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">

                    {/* County */}
                    <div>
                      <label className="text-sm text-gray-600">
                        County
                      </label>

                      <select
                        value={selectedCounty}
                        onChange={(e) =>
                          setSelectedCounty(e.target.value)
                        }
                        className="w-full mt-1 p-3 border rounded-lg bg-white"
                      >
                        <option value="">
                          Select County
                        </option>

                        {counties.map((county) => (
                          <option
                            key={county}
                            value={county}
                          >
                            {county}
                          </option>
                        ))}

                      </select>
                    </div>


                    {/* Constituency */}
                    <div>
                      <label className="text-sm text-gray-600">
                        Constituency
                      </label>

                      <select
                        value={selectedConstituency}
                        onChange={(e) =>
                          setSelectedConstituency(e.target.value)
                        }
                        disabled={!selectedCounty}
                        className="w-full mt-1 p-3 border rounded-lg bg-white disabled:bg-gray-100"
                      >

                        <option value="">
                          Select Constituency
                        </option>

                        {constituencies.map((item) => (
                          <option
                            key={item}
                            value={item}
                          >
                            {item}
                          </option>
                        ))}

                      </select>
                    </div>


                    {/* Ward */}
                    <div>
                      <label className="text-sm text-gray-600">
                        Ward
                      </label>

                      <select
                        value={selectedWard}
                        onChange={(e) =>
                          setSelectedWard(e.target.value)
                        }
                        disabled={!selectedConstituency}
                        className="w-full mt-1 p-3 border rounded-lg bg-white disabled:bg-gray-100"
                      >

                        <option value="">
                          Select Ward
                        </option>

                        {wards.map((ward) => (
                          <option
                            key={ward}
                            value={ward}
                          >
                            {ward}
                          </option>
                        ))}

                      </select>
                    </div>

                  </div>


                  {/* Service */}
                  <div className="mb-4">

                    <label className="text-sm text-gray-600">
                      Service
                    </label>

                    <select
                      value={service}
                      onChange={(e) =>
                        setService(e.target.value)
                      }
                      className="w-full mt-1 p-3 border rounded-lg bg-white"
                    >

                      <option value="">
                        Select Service
                      </option>

                      <option>
                        Eye Examination
                      </option>

                      <option>
                        Prescription Lenses
                      </option>

                      <option>
                        Frame Design
                      </option>

                      <option>
                        Reading Glasses
                      </option>

                      <option>
                        Optical Accessories
                      </option>

                    </select>

                  </div>


                  {/* Appointment Date */}
                  <div className="mb-4">

                    <label className="text-sm text-gray-600">
                      Appointment Date
                    </label>

                    <input
                      type="date"
                      value={appointmentDate}
                      onChange={(e) =>
                        setAppointmentDate(e.target.value)
                      }
                      min={today}
                      max={maxDate}
                      className="w-full mt-1 p-3 border rounded-lg"
                    />

                  </div>


                  {/* Budget */}
                  <div className="mb-6">

                    <label className="text-sm text-gray-600">
                      Budget Range
                    </label>

                    <select
                      value={budget}
                      onChange={(e) =>
                        setBudget(e.target.value)
                      }
                      className="w-full mt-1 p-3 border rounded-lg"
                    >

                      <option value="">
                        Select Budget
                      </option>

                      <option>
                        KSh 3,500 - 5,000
                      </option>

                      <option>
                        KSh 5,000 - 7,000
                      </option>

                      <option>
                        KSh 7,000 - 10,000
                      </option>

                      <option>
                        KSh 10,000+
                      </option>

                    </select>

                  </div>


                  {/* Check Availability */}
                  <button
                    onClick={() => {

                      if (
                        !selectedCounty ||
                        !selectedConstituency ||
                        !selectedWard ||
                        !service ||
                        !appointmentDate ||
                        !budget
                      ) {
                        alert(
                          "Please complete all booking details."
                        );

                        return;
                      }

                      setShowConfirmation(true);

                    }}
                    className="w-full bg-sky-400 hover:bg-sky-700 text-white py-3 rounded-lg font-black transition"
                  >
                    Check Availability
                  </button>

                </>


              ) : (

                <>
                  {/* Customer Name */}
                  <div className="mb-4">

                    <label className="text-sm text-gray-600">
                      Full Name
                    </label>

                    <input
                      type="text"
                      value={fullName}
                      onChange={(e) =>
                        setFullName(e.target.value)
                      }
                      placeholder="Enter your full name"
                      className="w-full mt-1 p-3 border rounded-lg"
                    />

                  </div>


                  {/* Phone */}
                  <div className="mb-4">

                    <label className="text-sm text-gray-600">
                      Phone Number
                    </label>

                    <input
                      type="tel"
                      value={phone}
                      onChange={(e) =>
                        setPhone(e.target.value)
                      }
                      placeholder="07XXXXXXXX"
                      className="w-full mt-1 p-3 border rounded-lg"
                    />

                  </div>
                                    {/* Email */}
                  <div className="mb-4">

                    <label className="text-sm text-gray-600">
                      Email Address
                    </label>

                    <input
                      type="email"
                      value={email}
                      onChange={(e) =>
                        setEmail(e.target.value)
                      }
                      placeholder="example@gmail.com"
                      className="w-full mt-1 p-3 border rounded-lg"
                    />

                  </div>


                  {/* Appointment Time */}
                  <div className="mb-5">

                    <label className="text-sm text-gray-600">
                      Preferred Appointment Time
                    </label>

                    <select
                      value={appointmentTime}
                      onChange={(e) =>
                        setAppointmentTime(e.target.value)
                      }
                      className="w-full mt-1 p-3 border rounded-lg bg-white"
                    >

                      <option value="">
                        Select Time
                      </option>

                      <option>08:00 AM</option>
                      <option>09:00 AM</option>
                      <option>10:00 AM</option>
                      <option>11:00 AM</option>
                      <option>12:00 PM</option>
                      <option>01:00 PM</option>
                      <option>02:00 PM</option>
                      <option>03:00 PM</option>
                      <option>04:00 PM</option>
                      <option>05:00 PM</option>

                    </select>

                  </div>


                  {/* Action Buttons */}
                  <div className="flex gap-3">

                    {/* Back Button */}
                    <button
                      onClick={() =>
                        setShowConfirmation(false)
                      }
                      className="w-1/3 bg-gray-500 hover:bg-gray-700 text-white py-3 rounded-lg font-medium transition"
                    >
                      Back
                    </button>


                    {/* WhatsApp Confirmation */}
                    <button
                      onClick={handleWhatsAppBooking}
                      className="w-2/3 bg-green-600 hover:bg-green-700 text-white py-3 rounded-lg font-semibold transition"
                    >
                      Confirm on WhatsApp
                    </button>

                  </div>

                </>

              )}


    </div>
        )}
</div>
</div>
        {/* Statistics */}
        <div className="mt-12 pt-6 border-t border-white/20">

          <div className="flex flex-wrap justify-center gap-6 md:gap-12 text-white">


            <div className="flex items-center gap-2">

              <span className="text-green-400 text-xl">
                ✔
              </span>

              <span>
                10,000+ Eye Tests Completed
              </span>

            </div>


            <div className="flex items-center gap-2">

              <span className="text-green-400 text-xl">
                ✔
              </span>

              <span>
                Certified Optometrists
              </span>

            </div>


            <div className="flex items-center gap-2">

              <span className="text-green-400 text-xl">
                ✔
              </span>

              <span>
                Premium Lens Technology
              </span>

            </div>


            <div className="flex items-center gap-2">

              <span className="text-green-400 text-xl">
                ✔
              </span>

              <span>
                Same Day Service Available
              </span>

            </div>


          </div>

        </div>


      </div>
{/* Appointment Popup */}
{showAppointmentPopup && (
  <div
    className="
      fixed inset-0 
      bg-black/70 
      backdrop-blur-sm
      z-50
      flex items-center justify-center
      p-4
    "
    onClick={() => setShowAppointmentPopup(false)}
  >

    {/* Card */}
    <div
      className="
        bg-[#f3f1eb]
        w-full
        max-w-lg
        p-8
        rounded-2xl
        shadow-2xl
        relative
        border border-sky-200
      "
      onClick={(e) => e.stopPropagation()}
    >

      {/* Close Button */}
      <button
        onClick={() => setShowAppointmentPopup(false)}
        className="
          absolute
          top-4
          right-5
          text-3xl
          hover:rotate-90
          transition-transform
          duration-300
        "
      >
        ×
      </button>


      {/* Heading */}
      <h2 className="text-3xl font-black uppercase mb-8">
        Confirm Your 
        <span className="text-sky-400">
          {" "}Appointment
        </span>
      </h2>


      {/* Form */}
      <div className="space-y-5">

        {/* Name */}
        <div>
          <label className="font-semibold block mb-2">
            Full Name
          </label>

          <input
            type="text"
            placeholder="Enter your full name"
            value={fullName}
            onChange={(e) => setFullName(e.target.value)}
            className="
              w-full
              border border-gray-300
              rounded-lg
              px-4 py-3
              outline-none
              focus:border-sky-400
            "
          />
        </div>


        {/* Phone */}
        <div>
          <label className="font-semibold block mb-2">
            Phone Number
          </label>

          <input
          type="tel"
          placeholder="07XXXXXXXX"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="
          w-full
          border border-gray-300
          rounded-lg
          px-4 py-3
          outline-none
          focus:border-sky-400
        "
      />
        </div>


        {/* Email */}
        <div>
          <label className="font-semibold block mb-2">
            Email Address
          </label>

          <input
          type="email"
          placeholder="example@gmail.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="
            w-full
            border border-gray-300
            rounded-lg
            px-4 py-3
            outline-none
            focus:border-sky-400
            "
            />
        </div>


        {/* Time */}
        <div>
          <label className="font-semibold block mb-2">
            Preferred Appointment Time
          </label>
          <select
            value={appointmentTime}
            onChange={(e) => setAppointmentTime(e.target.value)}
            className="
                w-full
                border border-gray-300
                rounded-lg
                px-4 py-3
                outline-none
                focus:border-sky-400
                "
                >
  <option value="">Select Time</option>
  <option>08:00 AM</option>
  <option>09:00 AM</option>
  <option>10:00 AM</option>
  <option>11:00 AM</option>
  <option>12:00 PM</option>
  <option>02:00 PM</option>
  <option>03:00 PM</option>
  <option>04:00 PM</option>
</select>
        </div>


        {/* WhatsApp Button */}
        <button
        onClick={handleAppointmentWhatsApp}
          className="
            w-full
            bg-sky-400
            hover:bg-sky-700
            text-white
            px-6
            py-4
            rounded-lg
            font-bold
            transition
            mt-4
          "
        >
          Confirm on WhatsApp →
        </button>

      </div>

    </div>

  </div>
)}
    </section>

  );

};


export default Home;